// EDIT THIS NODE when adding monitors. Keys are lowercase Uptime Kuma monitor names.
const config = {
  ntfyBaseUrl: 'http://ntfy:80',
  ntfyTopic: 'homelab-approvals',
  approvalMinutes: 15,
  cooldownMinutes: 30,
  recoveryDelaySeconds: 45,
  monitors: {
    sonarr: { container: 'sonarr', healthUrl: 'http://sonarr:8989/' },
    radarr: { container: 'radarr', healthUrl: 'http://radarr:7878/' },
    prowlarr: { container: 'prowlarr', healthUrl: 'http://prowlarr:9696/' },
    bazarr: { container: 'bazarr', healthUrl: 'http://bazarr:6767/' },
  },
};

const payload = $json.body ?? $json;
const monitorName = String(payload.monitor?.name ?? payload.monitorName ?? payload.name ?? '').trim();
const key = monitorName.toLowerCase();
const heartbeatStatus = payload.heartbeat?.status ?? payload.status;
const message = String(payload.msg ?? payload.message ?? 'Uptime Kuma reported a failure');
const target = config.monitors[key];
const isDown = heartbeatStatus === 0 || heartbeatStatus === '0' || heartbeatStatus === 'down' || heartbeatStatus === 'DOWN';

let accepted = Boolean(target && isDown);
let reason = !target ? 'monitor is not mapped' : (!isDown ? 'event is not DOWN' : 'accepted');
if (accepted) {
  const state = $getWorkflowStaticData('global');
  state.lastRequestedAt ??= {};
  const now = Date.now();
  const last = Number(state.lastRequestedAt[target.container] ?? 0);
  if (now - last < config.cooldownMinutes * 60 * 1000) {
    accepted = false;
    reason = `cooldown active (${config.cooldownMinutes} minutes)`;
  } else {
    state.lastRequestedAt[target.container] = now;
  }
}

return [{ json: { accepted, reason, monitorName, message, ...target, config } }];
